    byte[32] channelProvider,
    byte[32] channelProviderPayout,
    byte[32] channelVoucherDomainHash,
    int channelRefundAfterMs,
    int channelReserveSompi,
    int channelMaxSpendSompi,
    int channelCloseAfterMs
