    function requirePolicy() {
        require(reserveSompi >= 0);
        require(maxSpendSompi > 0);
        require(refundAfterMs > 0);
        require(closeAfterMs >= 0);
        if (closeAfterMs > 0) {
            require(closeAfterMs > refundAfterMs);
        }
    }

    function requireActiveChannel() {
        require(closeAfterMs == 0);
    }

    function requireClosingChannel() {
        require(closeAfterMs > 0);
    }

    function requireProviderPayout(int providerOutputIndex, int providerAmountSompi) {
        require(providerOutputIndex >= 0);
        require(providerAmountSompi > 0);
        byte[34] providerLock = new ScriptPubKeyP2PK(pubkey(providerPayout));
