        require(totalSpentSompi > 0);
        require(totalSpentSompi <= maxSpendSompi);
        require(totalSpentSompi <= inputValue - reserveSompi);
    }

    function requireContinuation(
        int channelOutputIndex,
        int newRefundAfterMs,
        int newMaxSpendSompi
    ) {
        int inputValue = tx.inputs[this.activeInputIndex].value;
        require(channelOutputIndex >= 0);
        require(newRefundAfterMs > refundAfterMs);
        require(newMaxSpendSompi > maxSpendSompi);
        require(newMaxSpendSompi <= tx.outputs[channelOutputIndex].value - reserveSompi);
        require(tx.outputs[channelOutputIndex].value > inputValue);
        validateOutputState(channelOutputIndex, State {
            payer: payer,
            provider: provider,
            providerPayout: providerPayout,
            voucherDomainHash: voucherDomainHash,
            refundAfterMs: newRefundAfterMs,
            reserveSompi: reserveSompi,
            maxSpendSompi: newMaxSpendSompi,
            closeAfterMs: 0
        });
    }

    function requireCloseContinuation(
        int channelOutputIndex,
        int newCloseAfterMs,
        int settlementFeeSompi
    ) {
        int inputValue = tx.inputs[this.activeInputIndex].value;
        int continuedValue = inputValue - settlementFeeSompi;
        require(channelOutputIndex >= 0);
        require(newCloseAfterMs > refundAfterMs);
        require(continuedValue > 0);
        require(continuedValue >= reserveSompi);
        require(tx.outputs[channelOutputIndex].value == continuedValue);
        validateOutputState(channelOutputIndex, State {
            payer: payer,
            provider: provider,
            providerPayout: providerPayout,
            voucherDomainHash: voucherDomainHash,
            refundAfterMs: refundAfterMs,
            reserveSompi: reserveSompi,
            maxSpendSompi: maxSpendSompi,
            closeAfterMs: newCloseAfterMs
        });
    }

    entry settle(
        sig payerSettleSig,
        sig providerSig,
        byte[32] settlementVoucherDomainHash,
        int totalSpentSompi,
        int settlementFeeSompi,
