    entry refund(sig payerSig, int settlementFeeSompi, int payerOutputIndex) {
        require(checkSig(payerSig, pubkey(payer)));
        requirePolicy();
        requireClosingChannel();
        require(settlementFeeSompi >= 0);
        require(tx.time >= temporal(closeAfterMs));

        int payerRefund = tx.inputs[this.activeInputIndex].value - settlementFeeSompi;
        requirePayerRefund(payerOutputIndex, payerRefund);
    }

    entry cooperativeClose(
        sig payerSig,
        sig providerSig,
        byte[32] settlementVoucherDomainHash,
        int providerAmountSompi,
        int settlementFeeSompi,
        int providerOutputIndex,
        int payerRefundOutputIndex
    ) {
        require(checkSig(payerSig, pubkey(payer)));
        require(checkSig(providerSig, pubkey(provider)));
        requirePolicy();
        require(settlementFeeSompi >= 0);
        require(providerAmountSompi >= 0);
        require(providerAmountSompi <= maxSpendSompi);
        require(settlementVoucherDomainHash == voucherDomainHash);

        int payerRefund = tx.inputs[this.activeInputIndex].value - providerAmountSompi - settlementFeeSompi;
        require(payerRefund >= 0);
        if (providerAmountSompi > 0) {
            requireProviderPayout(providerOutputIndex, providerAmountSompi);
        }
        if (payerRefund > 0) {
            requirePayerRefund(payerRefundOutputIndex, payerRefund);
